// Stockfish runs in an isolated worker; the UI can terminate it on pause or resignation.
import {botTiming} from './game-core.js';
export function stockfishThinkTime(clock,increment=0){return botTiming(4,clock,increment).budget}
export class StockfishOpponent{
 constructor(){this.onmessage=null;this.onerror=null;this.closed=false;this.ready=false;this.pending=null;this.watchdog=setTimeout(()=>this.fail('Stockfish did not load.'),20000);this.loading=this.load()}
 async load(){try{const response=await fetch('https://unpkg.com/stockfish@19.0.1/bin/stockfish-19-lite-single.wasm');if(!response.ok)throw Error('Stockfish download failed. Please retry.');const unpacked=await response.arrayBuffer();const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',unpacked))].map(n=>n.toString(16).padStart(2,'0')).join('');if(hash!=='ee4f115bdb2d32cadf96cada104a05b5ec257d7ad6f57582190b49bc71f096de')throw Error('Stockfish download failed verification. Please retry.');if(this.closed)return;this.wasmURL=URL.createObjectURL(new Blob([unpacked],{type:'application/wasm'}));const engineURL=new URL('./vendor/stockfish/stockfish-19-lite-single.js',import.meta.url);engineURL.hash=encodeURIComponent(this.wasmURL);this.worker=new Worker(engineURL);this.worker.onerror=e=>this.fail(e.message||'Stockfish could not load.');this.worker.onmessage=({data})=>{for(const line of String(data).split('\n'))this.receive(line.trim())};this.worker.postMessage('uci')}catch(e){this.fail(e.message)}}

 fail(message){if(this.closed)return;this.onerror?.({message});this.terminate()}
 receive(line){if(this.closed)return;if(line==='uciok'){this.worker.postMessage('setoption name Hash value 32');this.worker.postMessage('setoption name Skill Level value 20');this.worker.postMessage('setoption name UCI_LimitStrength value false');this.worker.postMessage('isready')}else if(line==='readyok'){this.ready=true;clearTimeout(this.watchdog);this.start()}else if(line.startsWith('bestmove ')&&this.pending){const code=line.split(/\s+/)[1],id=this.pending.id;clearTimeout(this.watchdog);this.pending=null;if(!/^[a-h][1-8][a-h][1-8][qrbn]?$/.test(code))return this.fail('Stockfish returned no legal move.');this.onmessage?.({data:{id,move:{from:code.slice(0,2),to:code.slice(2,4),...(code[4]?{promotion:code[4]}:{})}}})}}
 postMessage(data){if(this.closed)return;this.pending=data;if(this.ready)this.start()}
 start(){if(!this.pending||this.closed)return;const d=this.pending;this.worker.postMessage('ucinewgame');const base=d.initialFen?'fen '+d.initialFen:'startpos';this.worker.postMessage(d.history?'position '+base+(d.history.length?' moves '+d.history.join(' '):''):'position fen '+d.fen);this.watchdog=setTimeout(()=>this.fail('Stockfish took too long. Please retry.'),d.thinkMs+10000);this.worker.postMessage('go movetime '+d.thinkMs)}
 terminate(){if(this.closed)return;this.closed=true;clearTimeout(this.watchdog);this.pending=null;this.worker?.terminate();if(this.wasmURL)URL.revokeObjectURL(this.wasmURL)}
}
